<template><SuperAdminLayout><main class="page"><header><h1>7.2 Emergency Shutdown Report</h1></header><section><form @submit.prevent="load(1)"><label>Date From<input v-model="q.from_date" type="date"></label><label>Date To<input v-model="q.to_date" type="date"></label><label>Customer No.<input v-model="q.customer" placeholder="Enter Customer No."></label><label>Reason Type<select v-model="q.reason"><option value="">All</option><option>Security Review</option><option>System Maintenance</option><option>Security Risk</option></select></label><label>Shutdown Scope<select v-model="q.scope"><option value="">All</option><option value="entire_platform">Entire Platform</option><option value="all_customers">All Customers</option><option value="one_customer">One Customer</option></select></label><label>Status<select v-model="q.status"><option value="">All</option><option value="active">Active</option><option value="completed">Completed</option></select></label><div><button class="primary">Search</button><button type="button" @click="reset">Reset</button></div></form><div class="table"><table><thead><tr><th>No.</th><th>Date</th><th>Customer No.</th><th>Start Date / Time</th><th>Expected Restore</th><th>Reason Type</th><th>Shutdown Scope</th><th>Status</th></tr></thead><tbody><tr v-for="(x,i) in rows" :key="x.id"><td>{{no(i)}}</td><td>{{date(x.starts_at)}}</td><td>{{x.customer_id?`CUST-${String(x.customer_id).padStart(6,'0')}`:'—'}}</td><td>{{date(x.starts_at)}}</td><td>{{date(x.expected_restore_at)}}</td><td>{{x.reason}}</td><td>{{title(x.scope)}}</td><td><b :class="x.status">{{title(x.status)}}</b></td></tr><tr v-if="!rows.length"><td colspan="8">No emergency shutdown records found.</td></tr></tbody></table></div><footer><span>Showing {{rows.length}} of {{meta.total||0}} records</span><div><button :disabled="!meta.prev_page_url" @click="load(meta.current_page-1)">‹</button><b>{{meta.current_page||1}}</b><button :disabled="!meta.next_page_url" @click="load(meta.current_page+1)">›</button></div></footer></section></main></SuperAdminLayout></template>
<script setup>import{onMounted,reactive,ref}from'vue';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const rows=ref([]),meta=ref({}),q=reactive({from_date:'',to_date:'',customer:'',reason:'',scope:'',status:''}),title=v=>String(v||'—').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase()),date=v=>v?new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'—',no=i=>((meta.value.current_page||1)-1)*(meta.value.per_page||10)+i+1;async function load(page=1){const r=await client.get('/super-admin/emergency-shutdowns',{params:{...q,page}}),d=r.data.data||{};rows.value=d.data||[];meta.value=d}function reset(){Object.assign(q,{from_date:'',to_date:'',customer:'',reason:'',scope:'',status:''});load()}onMounted(load)</script>
<style scoped>.page{color:#071541}.page h1{margin:0 0 18px;font-size:2rem}section{padding:16px;border:1px solid #dbe4ef;border-radius:7px;background:#fff}form{display:grid;grid-template-columns:repeat(6,1fr);gap:13px 18px}label{display:grid;gap:6px;font-size:.69rem;font-weight:800}input,select,button{height:36px;border:1px solid #cad8ed;border-radius:5px;background:#fff;padding:0 10px;font:500 .76rem inherit}form div{display:flex;gap:10px;align-items:end}.primary{background:#073ec6;border-color:#073ec6;color:#fff;font-weight:700}.table{margin-top:15px;overflow:auto;border:1px solid #dce5ef}.table table{width:100%;min-width:900px;border-collapse:collapse;font-size:.7rem}.table th,.table td{padding:10px 8px;border:1px solid #e3e9f2;text-align:center}.table th{background:linear-gradient(100deg,#03205f,#0751c7);color:#fff}.active,.completed{padding:3px 6px;border-radius:3px}.active{background:#ffe1e1;color:#ba0b0b}.completed{background:#dff7e5;color:#08732a}footer{display:flex;justify-content:space-between;padding:17px 5px 0;font-size:.75rem}footer div{display:flex;gap:8px}footer button,footer b{display:grid;place-items:center;min-width:31px;height:30px;padding:0}footer b{background:#0647d2;color:#fff;border-radius:5px}@media(max-width:900px){form{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){form{grid-template-columns:1fr}.page h1{font-size:1.55rem}}</style>
